// The input contract. Everything a video shows comes from a Project object (project.json),
// generated by scripts/plan_to_project.py from the edit plan. No video content lives in code.

export type Tone = "neutral" | "before" | "after" | "cta" | "product";
export type Direction = "left" | "right" | "up" | "down";

export type TransitionType =
  | "cut" // hard cut, no overlap
  | "fade" // cross-dissolve
  | "slide" // push the new shot in
  | "wipe" // soft-edged wipe, good for before -> after
  | "iris" // circle opening from the centre, hero reveal
  | "pushCut" // TikTok-native punch: hard cut + scale + 2-frame flash
  | "zoomThrough" // scale through the cut with a blur peak
  | "blurDissolve" // dissolve through a blur
  | "whip" // fast directional slide with motion blur
  | "flip" // 3D card flip, sparingly
  | "crossZoom"; // WebGL radial zoom blur (needs the angle GL renderer)

export type SceneTransition = { type: TransitionType; frames?: number; direction?: Direction };

export type CameraMove = "push" | "pull" | "pan" | "hold";
export type Camera = {
  move?: CameraMove;
  from?: number; // scale at scene start
  to?: number; // scale at scene end
  focus?: [number, number]; // 0..1 point that stays put while scaling (product, face)
  pan?: [number, number]; // pan distance as a fraction of the frame, e.g. [-0.08, 0]
};

export type Scene = {
  clip: string | null; // file name in public/clips without extension; null renders a placeholder
  in: number; // source timecode (s) of the planned cut
  start: number; // timeline seconds
  end: number;
  type?: string; // HOOK, PROBLEM, DEMO, REVEAL, CTA-CLOSE ...
  transition?: SceneTransition; // how this scene is entered (ignored on scene 1)
  accent?: "flash" | "lightLeak"; // overlay centred on this scene's cut, does not change timing
  camera?: Camera;
};

export type Zone = "top" | "upper" | "center" | "lower";

export type Overlay = {
  component: string; // key in components/registry.tsx
  start: number;
  end: number;
  zone?: Zone;
  tone?: Tone;
  props?: Record<string, unknown>;
};

export type Caption = { text: string; start: number; end: number };
export type Word = { text: string; start: number; end: number };
export type Punch = { at: number; scale?: number }; // keyword punch-in, seconds on the timeline
export type AudioCue = { src: string; at: number; volumeDb?: number };
export type Music = { src: string; volumeDb?: number; duckDb?: number };

export type Project = {
  fps?: number;
  width?: number;
  height?: number;
  duration: number; // seconds
  voice?: string | null; // path under public/
  music?: Music | null;
  sfx?: AudioCue[];
  captionStyle?: "karaoke" | "plain" | "none";
  scenes: Scene[];
  overlays?: Overlay[];
  captions?: Caption[];
  words?: Word[];
  punches?: Punch[];
};
